// Score eligible invoices and group them into ONE action per client.
// Rules live in docs/business_rules.md. Thresholds come from the Config node.
const cfg = $('Config').first().json;
const today = $now.toFormat('yyyy-MM-dd');
const gap = Number(cfg.contact_gap_days);

// 1) Clients this agent already contacted within the contact gap (from the Outreach Log)
const recentlyContacted = new Set();
for (const row of $('Read Outreach Log').all()) {
  if (!row.json.run_date || !row.json.client_id) continue;
  const ageDays = (new Date(today) - new Date(row.json.run_date)) / 86400000;
  if (ageDays < gap) recentlyContacted.add(row.json.client_id);
}

// 2) Priority score per invoice (0-100): balance 40%, days past due 35%,
//    days since last contact 15% (never contacted counts as 60), broken promises 10%
const scaled = (value, cap) => Math.max(0, Math.min(Number(value) / cap, 1));
const money = (n) => '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const clients = {};
for (const { json: inv } of $input.all()) {
  const since = inv.days_since_contact === '' || inv.days_since_contact == null ? null : Number(inv.days_since_contact);
  if (since !== null && since < gap) continue;          // the team contacted them recently
  if (recentlyContacted.has(inv.client_id)) continue;   // this agent contacted them recently

  const score = 100 * (0.40 * scaled(inv.balance, 100000) + 0.35 * scaled(inv.days_past_due, 180)
                     + 0.15 * scaled(since ?? 60, 60) + 0.10 * scaled(inv.broken_promises, 3));

  const c = clients[inv.client_id] ??= {
    client_id: inv.client_id, client_name: inv.client_name, industry: inv.industry,
    ap_contact_name: inv.ap_contact_name, ap_contact_email: inv.ap_contact_email,
    billing_partner: inv.billing_partner, billing_partner_email: inv.billing_partner_email,
    invoices: [], total_balance: 0, oldest_days_past_due: 0, priority_score: 0, broken_promises: 0,
  };
  c.invoices.push(`${inv.invoice_id} | issued ${inv.invoice_date} | ${money(inv.balance)} | ${inv.days_past_due} days past due`);
  c.total_balance += Number(inv.balance);
  c.oldest_days_past_due = Math.max(c.oldest_days_past_due, Number(inv.days_past_due));
  c.priority_score = Math.max(c.priority_score, score);
  c.broken_promises += Number(inv.broken_promises || 0);
}

// 3) Lane + tone, decided by the client's OLDEST eligible invoice
return Object.values(clients)
  .map((c) => {
    const d = c.oldest_days_past_due;
    const lane = d > Number(cfg.escalation_days) ? 'escalation' : 'client';
    const tone = lane === 'escalation' ? 'internal escalation' : d > 90 ? 'urgent' : d > 60 ? 'firm' : 'friendly';
    return { json: { ...c, lane, tone, invoice_count: c.invoices.length, invoice_lines: c.invoices.join('\n'),
                     total_balance: Math.round(c.total_balance * 100) / 100,
                     total_balance_fmt: money(c.total_balance), priority_score: Math.round(c.priority_score * 10) / 10 } };
  })
  .sort((a, b) => b.json.priority_score - a.json.priority_score);

