// 120+ days past due: no client email. Instead, one internal note per billing partner
// listing all of their escalated clients, so partners get a single digest.
const byPartner = {};
for (const { json: c } of $input.all()) {
  const p = byPartner[c.billing_partner_email] ??= { billing_partner: c.billing_partner,
    billing_partner_email: c.billing_partner_email, clients: [], total: 0 };
  p.clients.push(c);
  p.total += Number(c.total_balance);
}
const money = (n) => '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
return Object.values(byPartner).map((p) => {
  const first = p.billing_partner.split(' ')[0];
  const lines = p.clients.map((c) => `- ${c.client_name}: ${c.total_balance_fmt} across ${c.invoice_count} invoice(s), `
    + `oldest ${c.oldest_days_past_due} days past due${c.broken_promises ? `, ${c.broken_promises} broken promise(s) to pay` : ''}`);
  const body = [`Hi ${first},`, '',
    `The following ${p.clients.length === 1 ? 'client has' : `${p.clients.length} clients have`} balances more than 120 days past due `
    + `(${money(p.total)} in total). Collections has paused routine reminders and recommends a partner-level conversation:`, '',
    ...lines, '',
    'Could you reach out or let us know the status (dispute, payment plan, or write-off review)? The invoice detail is in the AR aging report.', '',
    'Thanks,', 'Billing & Collections'].join('\n');
  return { json: { ...p, client_ids: p.clients.map((c) => c.client_id), subject:
    `Action needed: ${p.clients.length} client${p.clients.length === 1 ? '' : 's'} over 120 days past due (${money(p.total)})`, body } };
});

// One log row per escalated client, so the 14-day contact rule also applies to them.
// (Runs after the partner drafts are created; one partner note covers several clients.)
const rows = [];
for (const { json: partner } of $('Group by billing partner').all()) {
  for (const c of partner.clients) {
    rows.push({ json: {
      run_date: $now.toFormat('yyyy-MM-dd'), lane: 'Partner escalation', client_id: c.client_id, client_name: c.client_name,
      recipient: partner.billing_partner_email, invoices: c.invoice_count, total_balance: c.total_balance,
      oldest_days_past_due: c.oldest_days_past_due, tone: 'internal escalation', priority_score: c.priority_score,
      draft_status: 'Draft created - awaiting review' } });
  }
}
return rows;

// One plain-text summary of today's run: what was drafted, escalated and skipped (and why).
const cfg = $('Config').first().json;
const logged = $input.all().map((i) => i.json);
const all = $('Read AR Aging').all().map((i) => i.json);
const money = (n) => '$' + Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 });
const count = (f) => all.filter(f).length;

const clientRows = logged.filter((r) => r.lane === 'Client reminder');
const escRows = logged.filter((r) => r.lane === 'Partner escalation');
const skipped = {
  'Disputed': count((r) => r.exception_type === 'Disputed'),
  'On a payment plan': count((r) => r.exception_type === 'Payment plan'),
  [`Under ${cfg.min_days_past_due} days past due`]: count((r) => Number(r.days_past_due) < Number(cfg.min_days_past_due)),
  [`Balance under ${money(cfg.min_balance)}`]: count((r) => Number(r.balance) < Number(cfg.min_balance)),
};
const lines = [
  `Collections Agent - daily run ${$now.toFormat('yyyy-MM-dd')}`, '',
  `Open invoices scanned: ${all.length} (${money(all.reduce((s, r) => s + Number(r.balance), 0))} open AR)`, '',
  `CLIENT REMINDERS - ${clientRows.length} Gmail drafts awaiting your review`,
  ...clientRows.map((r) => `  - ${r.client_name}: ${money(r.total_balance)}, ${r.oldest_days_past_due} days past due (${r.tone})`), '',
  `PARTNER ESCALATIONS (120+ days) - ${escRows.length} clients, ${money(escRows.reduce((s, r) => s + Number(r.total_balance), 0))}`,
  ...Object.entries(escRows.reduce((acc, r) => {
      const p = (acc[r.recipient] ??= { n: 0, total: 0 }); p.n += 1; p.total += Number(r.total_balance); return acc; }, {}))
    .sort((a, b) => b[1].total - a[1].total)
    .map(([email, p]) => `  - ${email.split('@')[0].replace('.', ' ').replace(/\b\w/g, (ch) => ch.toUpperCase())}: `
      + `${p.n} client${p.n === 1 ? '' : 's'}, ${money(p.total)} (one draft note)`), '',
  'SKIPPED (invoice count, a row can match more than one reason)',
  ...Object.entries(skipped).map(([k, v]) => `  - ${k}: ${v}`),
  '  - Also skipped: anything contacted in the last ' + cfg.contact_gap_days + ' days, and clients beyond the daily cap of ' + cfg.daily_limit, '',
  'Nothing was sent to clients. All emails are drafts in Gmail.',
];
return [{ json: { subject: `Collections Agent: ${clientRows.length} drafts, ${escRows.length} escalations`, body: lines.join('\n') } }];
